def transform(grid):
    h, w = len(grid), len(grid[0])
    barrier = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), None)
    if barrier is None:
        return [row[:] for row in grid]
    direction = -1 if barrier > h // 2 else 1
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (0, 2)}
    objects = []
    while cells:
        seed = cells.pop()
        color = grid[seed[0]][seed[1]]
        obj = {seed}
        stack = [seed]
        while stack:
            r, c = stack.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in cells and grid[p[0]][p[1]] == color:
                    cells.remove(p); obj.add(p); stack.append(p)
        objects.append([color, obj])
    # Process objects nearest the barrier first so objects stack without overlap.
    if direction < 0:
        order = sorted(range(len(objects)), key=lambda i: min(r for r,c in objects[i][1]))
    else:
        order = sorted(range(len(objects)), key=lambda i: -max(r for r,c in objects[i][1]))
    occupied = set().union(*(obj for _, obj in objects)) if objects else set()
    settled = []
    for i in order:
        color, obj = objects[i]
        occupied -= obj
        while True:
            moved = {(r+direction,c) for r,c in obj}
            if any(r <= barrier if direction < 0 else r >= barrier for r,c in moved):
                break
            if moved & occupied:
                break
            obj = moved
        occupied |= obj
        settled.append((color,obj))
    out = [[0]*w for _ in range(h)]
    out[barrier] = grid[barrier][:]
    for color,obj in settled:
        for r,c in obj: out[r][c]=color
    return out
